
/* ============================================================================
 * AMMU-NATION — district weapon, ammunition and armour stores
 * ==========================================================================*/
(function(){
  'use strict';if(!window.GameSystems)return;
  const STORES=Object.freeze([
    Object.freeze({id:'ammu-downtown',name:'AMMU-NATION · DOWNTOWN',x:-760,z:430,accent:0xff3b6b,stock:['ammo:pistol','weapon:bat','weapon:knife','weapon:smg','ammo:smg','armour:25']}),
    Object.freeze({id:'ammu-strip',name:'AMMU-NATION · THE STRIP',x:2260,z:330,accent:0xffd23f,stock:['ammo:pistol','weapon:crowbar','weapon:shotgun','ammo:shotgun','weapon:rifle','ammo:rifle','armour:50']}),
    Object.freeze({id:'ammu-crown',name:'AMMU-NATION · HILLS CITY',x:-5050,z:-860,accent:0x20e3ff,stock:['weapon:knife','weapon:crowbar','weapon:smg','ammo:smg','weapon:shotgun','ammo:shotgun','weapon:rifle','ammo:rifle','weapon:rpg','ammo:rpg','weapon:minigun','ammo:minigun','armour:50']})
  ]);
  const WEAPON_LABELS=Object.assign({pistol:'PISTOL',smg:'NEON SMG',shotgun:'PUMP SHOTGUN',rifle:'CARBINE'},MeleeCombatModule.shopLabels(),HeavyOrdnanceModule.shopLabels()),WEAPON_PRICES=Object.assign({smg:1600,shotgun:2400,rifle:4200},MeleeCombatModule.shopPrices(),HeavyOrdnanceModule.shopPrices()),AMMO=Object.assign({pistol:{amount:24,cost:120},smg:{amount:60,cost:360},shotgun:{amount:18,cost:270},rifle:{amount:60,cost:540}},HeavyOrdnanceModule.ammoProducts());
  let ctx=null,combat=null,prog=null,nav=null,interact=null,root=null,panel=null,open=null,selection=0,markers=[];
  const money=n=>'$'+Math.max(0,Math.round(n||0)).toLocaleString();
  function product(key){const[a,id]=key.split(':');if(a==='weapon')return{key,type:a,id,label:WEAPON_LABELS[id],cost:WEAPON_PRICES[id]||0};if(a==='ammo')return{key,type:a,id,label:(WEAPON_LABELS[id]||id)+' AMMO · +'+AMMO[id].amount,cost:AMMO[id].cost};const amount=+id||25;return{key,type:'armour',id:amount,label:'BODY ARMOUR · +'+amount,cost:amount>=50?650:350};}
  function state(){return combat.state?combat.state():{owned:{},ammo:{},armour:0};}
  function buy(item){let r;if(item.type==='weapon')r=combat.purchase(item.id);else if(item.type==='ammo')r=combat.purchaseAmmo(item.id);else r=combat.purchaseArmour(item.id);if(!r||!r.ok){ctx.fx.toast((r&&r.reason)||'Purchase failed','#ff6b6b');return false;}ctx.fx.banner('PURCHASED',item.label,'#3bff8b');ctx.fx.toast(item.label+' · '+money(r.cost),'#3bff8b');render();return true;}
  function ensureUi(){if(root)return;const css=document.createElement('style');css.id='ammuV16CSS';css.textContent='#ammuV16{position:absolute;inset:0;display:none;align-items:center;justify-content:center;background:rgba(3,5,10,.64);pointer-events:auto;z-index:72}#ammuV16.on{display:flex}#ammuV16 .box{width:min(720px,94vw);max-height:86vh;display:flex;flex-direction:column;border:1px solid var(--ac,#ff3b6b);border-radius:14px;background:linear-gradient(145deg,rgba(14,18,29,.98),rgba(5,8,14,.98));box-shadow:0 24px 90px #000;overflow:hidden}#ammuV16 header{display:flex;gap:12px;align-items:center;padding:15px 18px;border-bottom:1px solid #293348}#ammuV16 h2{flex:1;margin:0;color:var(--ac);font:950 18px/1 system-ui,sans-serif;letter-spacing:2px}#ammuV16 .wallet{color:#ffd23f;font:900 12px/1 system-ui,sans-serif}#ammuV16 .status{padding:9px 18px;color:#91a3ba;font:800 11px/1.35 system-ui,sans-serif;letter-spacing:.7px}#ammuV16 .list{padding:0 14px 14px;overflow:auto}#ammuV16 .row{display:flex;justify-content:space-between;gap:12px;padding:11px 13px;margin-top:7px;border:1px solid #2a3446;border-radius:9px;color:#dce8f7;font:850 12px/1.25 system-ui,sans-serif}#ammuV16 .row.sel{border-color:var(--ac);background:rgba(255,255,255,.055);transform:translateX(3px)}#ammuV16 .row small{display:block;margin-top:4px;color:#8292a8;font-size:10px}#ammuV16 .actions{display:flex;gap:8px;padding:12px 14px;border-top:1px solid #293348}#ammuV16 button{min-height:42px;padding:0 14px;border:1px solid #40506a;border-radius:9px;background:#101724;color:#e9f3ff;font:900 11px/1 system-ui,sans-serif;letter-spacing:.7px}#ammuV16 button.buy{border-color:#3bff8b;color:#3bff8b}body.ammu-open #mobileControls{display:none!important}';document.head.appendChild(css);root=document.createElement('div');root.id='ammuV16';root.innerHTML='<section class="box"><header><h2></h2><div class="wallet"></div></header><div class="status"></div><div class="list"></div><div class="actions"><button class="buy">ENTER · BUY</button><button class="close">ESC · CLOSE</button></div></section>';ctx.dom.ui.appendChild(root);panel={box:root.querySelector('.box'),title:root.querySelector('h2'),wallet:root.querySelector('.wallet'),status:root.querySelector('.status'),list:root.querySelector('.list'),buy:root.querySelector('.buy'),close:root.querySelector('.close')};panel.buy.onclick=()=>{if(open)buy(product(open.stock[selection]));};panel.close.onclick=closePanel;}
  function itemStatus(item,s){if(item.type==='weapon')return s.owned&&s.owned[item.id]?'OWNED':'WEAPON';if(item.type==='ammo'){const a=s.ammo&&s.ammo[item.id];return a?'RESERVE '+a.reserve:'AMMUNITION';}return'ARMOUR '+Math.round(s.armour||0)+'%';}
  function render(){if(!open)return;ensureUi();const s=state();selection=Math.max(0,Math.min(selection,open.stock.length-1));panel.box.style.setProperty('--ac','#'+open.accent.toString(16).padStart(6,'0'));panel.title.textContent=open.name;panel.wallet.textContent='WALLET '+money(prog.wallet());panel.status.textContent='WEAPONS · AMMUNITION · ARMOUR  |  ↑/↓ SELECT · ENTER BUY · ESC CLOSE';panel.list.textContent='';open.stock.forEach((key,i)=>{const item=product(key),row=document.createElement('div');row.className='row'+(i===selection?' sel':'');row.innerHTML='<div>'+item.label+'<small>'+itemStatus(item,s)+'</small></div><div>'+money(item.cost)+'</div>';row.onclick=()=>{selection=i;render();};panel.list.appendChild(row);});}
  function openPanel(store){if(!ctx.player.onFoot){ctx.fx.toast('Enter Ammu-Nation on foot','#ff6b6b');return;}open=store;selection=0;ensureUi();root.classList.add('on');document.body.classList.add('ammu-open');render();}
  function closePanel(){open=null;if(root)root.classList.remove('on');document.body.classList.remove('ammu-open');}
  function marker(store){const T=ctx.THREE,g=new T.Group(),mat=new T.MeshBasicMaterial({color:store.accent,transparent:true,opacity:.82,depthWrite:false}),ring=new T.Mesh(new T.TorusGeometry(4,.34,6,28),mat),sign=new T.Mesh(new T.BoxGeometry(5.2,2.2,.45),new T.MeshBasicMaterial({color:store.accent}));ring.rotation.x=Math.PI/2;ring.position.y=.25;sign.position.y=5.4;g.add(ring,sign);g.position.set(store.x,ctx.world.groundHeightAt(store.x,store.z,0)+.08,store.z);g.userData.ring=ring;ctx.scene.add(g);markers.push(g);return g;}
  GameSystems.register({id:'ammu',order:57,requires:['save','progression','nav','interact','combat'],alwaysUpdate:true,
    init(c){ctx=c;combat=GameSystems.api('combat');prog=GameSystems.api('progression');nav=GameSystems.api('nav');interact=GameSystems.api('interact');ensureUi();for(const store of STORES){marker(store);interact.addPrompt({id:store.id,worldId:'neon',x:store.x,z:store.z,radius:12,maxSpeedMph:5,color:'#'+store.accent.toString(16).padStart(6,'0'),label:'ENTER '+store.name,when:c=>c.player.onFoot,onTrigger:()=>openPanel(store)});interact.addPrompt({id:store.id+'-vehicle',worldId:'neon',x:store.x,z:store.z,radius:12,maxSpeedMph:5,color:'#'+store.accent.toString(16).padStart(6,'0'),label:'EXIT VEHICLE TO ENTER '+store.name,when:c=>!c.player.onFoot,onTrigger:()=>ctx.fx.toast('Exit the vehicle, then press E at the door','#ffd23f')});nav.addPOI({id:store.id,worldId:'neon',x:store.x,z:store.z,icon:'A',label:store.name,kind:'ammu',color:'#'+store.accent.toString(16).padStart(6,'0')});}const help=GameSystems.api('help');if(help)help.addControls('AMMU-NATION',[['Walk to A','Open store'],['↑ / ↓','Select stock'],['Enter','Purchase'],['Esc','Close']]);},
    update(dt){const live=ctx.world.id==='neon',pulse=1+Math.sin(performance.now()/260)*.09;for(const m of markers){m.visible=live;m.userData.ring.rotation.z+=dt*.8;m.scale.setScalar(pulse);}if(open){ctx.player.foot.walk=0;panel.wallet.textContent='WALLET '+money(prog.wallet());}},
    onKey(k){if(!open)return false;if(k==='escape'){closePanel();return true;}if(k==='arrowdown'||k==='s'){selection=(selection+1)%open.stock.length;render();return true;}if(k==='arrowup'||k==='w'){selection=(selection+open.stock.length-1)%open.stock.length;render();return true;}if(k==='enter'||k==='g'){buy(product(open.stock[selection]));return true;}return true;},
    dispose(){closePanel();for(const store of STORES){interact.removePrompt(store.id);interact.removePrompt(store.id+'-vehicle');nav.removePOI(store.id);}for(const m of markers)if(m.parent)m.parent.remove(m);},
    api:{get isOpen(){return!!open;},stores:()=>STORES.map(s=>({id:s.id,name:s.name,x:s.x,z:s.z,stock:s.stock.slice()})),open(id){const s=STORES.find(x=>x.id===id);if(s)openPanel(s);return!!s;},close:closePanel}
  });
})();
